template <typename Rep> void numeric_sign_property() {
  using duration = std::chrono::duration<Rep>;
  for (const char* a : {"%S", "%Q", "%R", "%T", "%H", "%M"})
    for (const char* b : {"%S", "%Q", "%R", "%T", "%H", "%M"})
      for (const char* precision : {"", ".2"})
        for (Rep magnitude : {Rep(1), Rep(1.25), Rep(61.25), Rep(3601.5),
                              std::numeric_limits<Rep>::infinity()}) {
          auto pattern = std::string("{:") + precision + a + " " + b + "}";
          EXPECT_EQ("-" + fmt::format(fmt::runtime(pattern), duration(magnitude)),
                    fmt::format(fmt::runtime(pattern), duration(-magnitude)));
        }
}
TEST(property, numeric_first_unpadded_sign) {
  numeric_sign_property<float>();
  numeric_sign_property<double>();
  numeric_sign_property<long double>();
}
TEST(property, independent_oracles) {
  using duration = std::chrono::duration<double>;
  EXPECT_EQ("01.250000 61.25", fmt::format("{:%S %Q}", duration(61.25)));
  EXPECT_EQ("-01.250000 61.25", fmt::format("{:%S %Q}", duration(-61.25)));
  EXPECT_EQ("inf inf", fmt::format("{:%Q %S}", duration(INFINITY)));
  EXPECT_EQ("-inf inf", fmt::format("{:%Q %S}", duration(-INFINITY)));
  EXPECT_EQ("01 61 00:01:01", fmt::format("{:%S %Q %T}", std::chrono::seconds(61)));
  EXPECT_EQ("-01 61 00:01:01", fmt::format("{:%S %Q %T}", std::chrono::seconds(-61)));
}

